    private static Formula Call(string name, params Formula[] args) =>
        new Formula.Apply(F.Id(name), [.. args]);
    private static Formula Q(params string[] names) => Seq([.. names.SelectMany(
        (name, index) => index == 0
            ? new Formula[] { Operatorname, Grp(F.Id(name)) }
            : [Dot, Operatorname, Grp(F.Id(name))])]);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
    private static Formula Complex => Seq(Mathbb, Grp(F.Id("C")));
    private static Formula Integer => Seq(Mathbb, Grp(F.Id("Z")));
    private static Formula PositiveNatural => Seq(Mathbb, Grp(F.Id("N")), Caret, Grp(Plus));
}
